/**
 * MorphoNews Layout: テクトニック・フラクチャー・フロー
 * Generated: 2026-02-28_0950
 * Generation: #92
 * Mood: Turbulent
 * Evolution: 12-column asymmetric subgrid + Scroll-driven Skew/Translate parallax + high-contrast tectonic shadows
 * Description: 第93世代の進化として、前回の「整然とした3Dプリズム」から、不規則で高エネルギーな「地殻変動的破砕（Turbulent Fracture）」へとコンセプトを転換しました。12カラムの精密なサブグリッドを敢えて崩し、各カードが異なるスパンとオフセットを持つことで、情報の断層が生み出す動的なリズムを表現しています。Scroll-driven Animationsにより、スクロール量に応じてカードが左右に微細に歪み（Skew）、重なり合うボーダーと影が干渉し合うことで、情報の「隆起」と「沈降」を視覚化。静止時でも不安定な緊張感を保つ、前衛的な「Turbulent」ムードを体現しています。
 */
:root {
    --layout-max-width: 1600px;
    --layout-news-columns: repeat(12, 1fr);
    --layout-card-gap: 3rem;
    --layout-card-direction: column;
    --layout-animation-style: tectonic-shift;
    --tectonic-shadow: 12px 12px 0px;
}

#news-container {
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    max-width: var(--layout-max-width);
    margin: 8rem auto;
    padding: 0 4rem;
    align-items: start;
}

.news-card {
    position: relative;
    background: var(--morpho-bg-secondary);
    border: 2px solid var(--morpho-text-primary);
    box-shadow: var(--tectonic-shadow) var(--morpho-accent-primary);
    padding: 1.5rem;
    transition: transform 0.4s cubic-bezier(0.23, 1, 0.32, 1), box-shadow 0.4s ease;

    /* Scroll-driven Animation Setup */
    view-timeline: --card-scroll block;
    animation: tectonic-shift linear both;
    animation-timeline: --card-scroll;
    animation-range: entry 5% exit 95%;
}

/* アシンメトリックなグリッド配置の定義 */
.news-card:nth-child(4n+1) {
    grid-column: 1 / span 7;
    margin-top: 0;
}

.news-card:nth-child(4n+2) {
    grid-column: 8 / span 5;
    margin-top: 10rem;
}

.news-card:nth-child(4n+3) {
    grid-column: 2 / span 5;
    margin-top: -5rem;
}

.news-card:nth-child(4n+4) {
    grid-column: 7 / span 6;
    margin-top: 4rem;
}

@keyframes tectonic-shift {
    0% {
        transform: translateY(150px) skewY(4deg) scale(0.95);
        opacity: 0;
        filter: grayscale(1) blur(4px);
    }
    20% {
        opacity: 1;
        filter: grayscale(0) blur(0);
    }
    50% {
        transform: translateY(0) skewY(0deg) scale(1);
    }
    80% {
        opacity: 1;
    }
    100% {
        transform: translateY(-150px) skewY(-4deg) scale(0.95);
        opacity: 0;
    }
}

.news-card::before {
    content: '';
    position: absolute;
    top: -10px;
    left: -10px;
    width: 40px;
    height: 40px;
    border-top: 4px solid var(--morpho-accent-secondary);
    border-left: 4px solid var(--morpho-accent-secondary);
    z-index: 1;
}

.news-card:hover {
    transform: translate(-8px, -8px) scale(1.02) !important;
